/**
 * Agent portrait crests: the data map the HUD (and any other package) imports without depending on packages/web.
 * The PNGs are generated by assets/pixel/composed/scripts/crests.py from the repo's own village sprites (32x32, pixelated).
 * `crestPath` is a repo-relative path for `assetUrl()`; `crestIdForAgent` resolves any agent id (HUD agents, council seats).
 */
export const CREST_IDS = [
  'skeptic',
  'teacher',
  'practitioner',
  'solver-a',
  'solver-b',
  'solver-c',
  'debate-pro',
  'debate-con',
  'judge',
  'examiner',
  'quizkey',
  'debate',
  'planner',
  'feynman',
  'stepdiff',
  'oracle',
  'oral',
  'rubric',
  'devil',
  'ch1',
  'ch2',
  'ch3',
  'ch4',
  'ch5',
  'dean',
  'student',
] as const;
export type CrestId = (typeof CREST_IDS)[number];

export const CREST_DIR = 'assets/pixel/composed/characters/crests';
export const crestPath = (id: CrestId): string => `${CREST_DIR}/${id}.png`;

/** Plain-words role for tooltips: 'Agent Hall: runs the quiz council'. */
export const CREST_ROLE: Record<CrestId, string> = {
  skeptic: 'Challenges weak steps',
  teacher: 'Brings the course notes',
  practitioner: 'Weighs what works on an exam',
  'solver-a': 'Solves independently',
  'solver-b': 'Solves independently',
  'solver-c': 'Solves independently',
  'debate-pro': 'Argues for',
  'debate-con': 'Argues against',
  judge: 'Judges the debate',
  examiner: 'Tests the answer',
  quizkey: 'Agent Hall quiz council',
  debate: 'Debate Stage council',
  planner: 'Course-planning round table',
  feynman: 'Explains it simply',
  stepdiff: 'Finds where your steps diverge',
  oracle: 'Predicts the exam',
  oral: 'Runs the oral exam',
  rubric: 'Grades against the rubric',
  devil: 'Argues the other side',
  ch1: 'Chapter 1 expert',
  ch2: 'Chapter 2 expert',
  ch3: 'Chapter 3 expert',
  ch4: 'Chapter 4 expert',
  ch5: 'Chapter 5 expert',
  dean: 'Knows everyone',
  student: 'You',
};

const ALIAS: Record<string, CrestId> = {
  a: 'solver-a',
  b: 'solver-b',
  c: 'solver-c',
  pro: 'debate-pro',
  con: 'debate-con',
  'debate-pro': 'debate-pro',
  'debate-con': 'debate-con',
  'debate-judge': 'judge',
  mediator: 'planner',
};
const IDS = new Set<string>(CREST_IDS);

/** 'council:ask-skeptic' -> 'skeptic'; 'council:quizkey' -> 'quizkey'; 'expert:ch3' -> 'ch3'; unknown -> undefined. */
export function crestIdForAgent(agentId: string): CrestId | undefined {
  const k = agentId
    .replace(/^[a-z]+:/i, '')
    .replace(/^(ask|planner|roundtable|solve|solver|exam)-/i, '')
    .trim()
    .toLowerCase();
  if (IDS.has(k)) return k as CrestId;
  if (ALIAS[k]) return ALIAS[k];
  if (/^s_|^student/.test(agentId)) return 'student';
  return undefined;
}
